mapper.select:
select * from om_cloud_optimizer_page_tbl where 1=1
AND page_parent_no = #{page_parent_no}
AND page_parent_no = 0

mapper.update:
	 UPDATE om_cloud_optimizer_page_tbl
 	SET use_lazyload = #{use_lazyload}
 	WHERE page_no = #{page_no}

		UPDATE om_cloud_optimizer_page_tbl
    	SET use_lazyload = #{use_lazyload}
    	WHERE page_no != 0;

choose.when:
SELECT opsl.log_sn, opsl.page_url, opsl.created_at, opsl.duration, ocopt.page_no FROM om_page_speed_log opsl LEFT JOIN om_cloud_optimizer_page_tbl ocopt ON opsl.page_url = ocopt.page_url WHERE opsl.is_ok = 1 AND ocopt.page_type = 1 AND opsl.created_at >= date_trunc('day', current_date) AND opsl.created_at < date_trunc('day', current_date) + interval '1 day'
ORDER BY created_at DESC LIMIT
2000 #{limit}
